function(source) {
    let commands = [];

    source = source.replace(/\r/g, "");

    let lines = source.split("\n");

    let ifStack = [];

    function addCommand(command) {
    if (ifStack.length > 0) {
        let current = ifStack[ifStack.length - 1].argument;

        if (current.collectingElse) {
            current.elseBody.push(command);
        } else {
            current.body.push(command);
        }
    } else {
        commands.push(command);
    }
}

    for (let line of lines) {
        line = line.trim();

        if (line === "") continue;
        if (line.startsWith("//")) continue;
        if (line.startsWith("header ")) continue;

        if (line.startsWith("if ") && line.endsWith(";")) {
            let condition = line.slice(3, -1).trim();

            let ifCommand = {
    command: "if",
    argument: {
        condition: condition,
        body: [],
        elseBody: [],
        collectingElse: false
    }
};

            ifStack.push(ifCommand);
            continue;
        }

        if (line === "else;") {
    if (ifStack.length > 0) {
        ifStack[ifStack.length - 1].argument.collectingElse = true;
    }

    continue;
}

        if (line === "end;") {
    let finishedIf = ifStack.pop();

    delete finishedIf.argument.collectingElse;

    addCommand(finishedIf);
    continue;
}

        if (line.endsWith(";")) {
            line = line.slice(0, -1).trim();

            let space = line.indexOf(" ");

            let commandName = line;
            let argument = "";

            if (space != -1) {
                commandName = line.substring(0, space);
                argument = line.substring(space + 1).trim();
            }

            if (commandName === "var") {
                let equals = argument.indexOf("=");

                if (equals != -1) {
                    let name = argument.substring(0, equals).trim();
                    let value = argument.substring(equals + 1).trim();

                    if (value.startsWith("\"") && value.endsWith("\"")) {
                        value = value.slice(1, -1);
                    }

                    addCommand({
                        command: "var",
                        argument: {
                            name: name,
                            value: value
                        }
                    });

                    continue;
                }
            }

            addCommand({
                command: commandName,
                argument: argument
            });
        }
    }

    return JSON.stringify(commands);
}
